INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(108061, 'ruRU', '', 'Нам стоит идти. Здесь нам больше нечего делать. Скажи мне, когда будешь готов уйти, и я верну нас обратно в наши тела в обычном мире.', 24330),
(108062, 'ruRU', '', 'Готов уйти?', 24330),
(108063, 'ruRU', '', 'Защитник, нам снова приходится просить тебя пойти туда, куда мы не можем последовать. Силы Хелии нужно ослабить, если мы хотим одержать победу.', 24330),
(108065, 'ruRU', '', 'Не перенапрягайся. Придёт время, когда Хелия столкнётся с полным гневом Одина. Но до тех пор ты ослабил её силы.', 24330),
(108078, 'ruRU', '', 'Мы встретимся снова, $n. Пусть Элуна направляет наши пути.', 24330),
(108085, 'ruRU', '', 'Демоны продолжают наступать на Врата Доблести. Требуется твоя помощь.', 24330),
(108086, 'ruRU', '', 'Ты хорошо потрудился сегодня, защитник. Пусть Круговерть Пустоты наполнится стенаниями твоих врагов.', 24330),
(108102, 'ruRU', '', 'Те твари там заряжены древней маной. Мне ужасно неловко просить тебя об этом, но мне нужно, чтобы ты расправился с ними и выкачал их энергию.', 24330),
(108104, 'ruRU', '', 'Спасибо. Это ужасный долг, но эта работа жизненно важна для нашего выживания.', 24330),
(108108, 'ruRU', '', 'Мы отправляемся в Храм Элуны. На спине Эш''алы мы доберёмся быстрее. Готов отправляться?', 24330),
(108109, 'ruRU', '', 'Мы отправляемся в Храм Элуны. На этот раз Эш''ала понесёт тебя. Приготовься.', 24330),
(108123, 'ruRU', '', 'Наконец-то мы приближаемся к ней после всех этих лет...', 24330),
(108124, 'ruRU', '', 'Встретимся наверху, в "Великолепных товарах", когда закончишь. Ещё одна из ищеек Кадгара тут вынюхивала, задавала слишком много вопросов...', 24330),
(108125, 'ruRU', '', 'Если у тебя нет при себе осколков лей-света, боюсь, я не смогу завершить ритуал.$b$bМожет, ты оставил немного в своём банке?', 24330),
(108143, 'ruRU', '', 'Держись в тенях, чтобы не быть замеченным. Кирин-Тор — не глупцы.', 24330),
(108152, 'ruRU', '', 'Капитан снимет с меня голову, если я не вернусь скоро...', 24330),
(108153, 'ruRU', '', 'Да, горожанин?', 24330),
(108154, 'ruRU', '', 'Излагай своё дело или проходи мимо. Я кое-кого жду.', 24330),
(108155, 'ruRU', '', 'Наконец-то, алмазные стабилизаторы, которые мы заказывали. Может, теперь силовые проводники перестанут замыкать.', 24330),
(108156, 'ruRU', '', 'Мой спарринг-партнёр Налтетис рассказал мне, что ты сделал. Из тебя вышел бы хороший солдат.', 24330),
(108158, 'ruRU', '', 'Эйир! Узри мои деяния, пока я рассекаю этого так называемого защитника.', 24330),
(108164, 'ruRU', '', 'Среди валькир есть те, кто желает испытать тебя в поединке. Отправляйся в Скольд-Ашил и сразись с ними. Никто не нападёт, пока ты не нанесёшь первый удар.', 24330),
(108171, 'ruRU', '', 'Я иду... в чертоги... доблести.', 24330),
(108179, 'ruRU', '', 'Я точно что-то слышал. Не волнуйся, архимаг, я их найду!', 24330),
(108182, 'ruRU', '', 'Мои обереги обнаружили, что кто-то вошёл в кабинет. Немедленно найдите их!', 24330),
(108183, 'ruRU', '', 'Защитник! Знай, что перед тобой Бретта, вестница твоей гибели.', 24330),
(108186, 'ruRU', '', 'Пусть у нас будет славная битва.', 24330),
(108187, 'ruRU', '', 'Я заявлю права на честь твоей смерти.', 24330),
(108188, 'ruRU', '', 'Я обагрю эту землю твоей кровью.', 24330),
(108189, 'ruRU', '', 'Акаари... твой час настал.', 24330),
(108190, 'ruRU', '', 'Эйир... направь меня к себе.', 24330),
(108191, 'ruRU', '', 'Я иду навстречу своей судьбе...', 24330),
(108192, 'ruRU', '', 'Лишь величайшие из валькир достойны дара Эйир.', 24330),
(108193, 'ruRU', '', 'Три павших брата Бога-Короля Сковальда восстали. Найди их, защитник, и напомни им, почему им стоит оставаться мёртвыми.', 24330),
(108194, 'ruRU', '', 'Четыре брата. Каждый приложил руку к убийству отца. Каждый приложил руку к убийству друг друга. И так Сковальд стал королём, ибо его клинок был быстрейшим.', 24330),
(108195, 'ruRU', '', 'Салон под контролем, $p.', 24330),
(108196, 'ruRU', '', 'Всё чисто, $p.', 24330),
(108197, 'ruRU', '', 'Акаари отступила наверх, когда мы прибыли. Она вся твоя.', 24330),
(108200, 'ruRU', '', 'Мне стоит тебя поблагодарить. Ты избавил меня от хлопот тебя искать.', 24330),
(108201, 'ruRU', '', 'Кил''джеден будет доволен, когда я принесу ему твою голову.', 24330);
